package br.edu.cs.poo.ac.seguro.entidades;
import java.io.Serializable; import java.math.BigDecimal; import java.time.LocalDateTime;
public class Sinistro implements Serializable { private static final long serialVersionUID=1L; private String numero; private Veiculo veiculo; private LocalDateTime dataHoraSinistro,dataHoraRegistro; private String usuarioRegistro; private BigDecimal valorSinistro; private TipoSinistro tipo; public Sinistro(String numero,Veiculo veiculo,LocalDateTime dataHoraSinistro,LocalDateTime dataHoraRegistro,String usuarioRegistro,BigDecimal valorSinistro,TipoSinistro tipo){this.numero=numero;this.veiculo=veiculo;this.dataHoraSinistro=dataHoraSinistro;this.dataHoraRegistro=dataHoraRegistro;this.usuarioRegistro=usuarioRegistro;this.valorSinistro=valorSinistro;this.tipo=tipo;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public Veiculo getVeiculo(){return veiculo;} public void setVeiculo(Veiculo v){veiculo=v;} public LocalDateTime getDataHoraSinistro(){return dataHoraSinistro;} public void setDataHoraSinistro(LocalDateTime v){dataHoraSinistro=v;} public LocalDateTime getDataHoraRegistro(){return dataHoraRegistro;} public void setDataHoraRegistro(LocalDateTime v){dataHoraRegistro=v;} public String getUsuarioRegistro(){return usuarioRegistro;} public void setUsuarioRegistro(String v){usuarioRegistro=v;} public BigDecimal getValorSinistro(){return valorSinistro;} public void setValorSinistro(BigDecimal v){valorSinistro=v;} public TipoSinistro getTipo(){return tipo;} public void setTipo(TipoSinistro v){tipo=v;} }
